css:
.sl-hero-dynamic {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 80vh;
  display: flex;
  align-items: center;
  padding-block: clamp(3.5rem, 7vw, 6rem);
}
.sl-hero-dynamic .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-dynamic .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-dynamic .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-dynamic .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-dynamic .sl-bg-primary {
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-dynamic .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 2px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-dynamic .sl-btn-primary:hover,
.sl-hero-dynamic .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-dynamic .sl-fw-black {
  font-weight: 900;
}
.sl-hero-dynamic .sl-tracking-wide {
  letter-spacing: 0.15em;
}
.sl-hero-dynamic .sl-skew-badge {
  transform: skewX(-15deg);
}
.sl-hero-dynamic .sl-btn-skew {
  transform: skewX(-15deg);
  transition: transform 0.25s ease, background-color 0.25s ease;
}
.sl-hero-dynamic .sl-unskew {
  transform: skewX(15deg);
}
[dir="rtl"] .sl-hero-dynamic .sl-skew-badge,
[dir="rtl"] .sl-hero-dynamic .sl-btn-skew {
  transform: skewX(15deg);
}
[dir="rtl"] .sl-hero-dynamic .sl-unskew {
  transform: skewX(-15deg);
}
.sl-hero-dynamic .sl-dynamic-image-wrapper {
  width: 62%;
  clip-path: polygon(16% 0, 100% 0, 100% 100%, 0% 100%);
}
[dir="rtl"] .sl-hero-dynamic .sl-dynamic-image-wrapper {
  inset-inline-start: auto;
  inset-inline-end: 0;
  clip-path: polygon(0 0, 84% 0, 100% 100%, 0% 100%);
}
.sl-hero-dynamic .sl-dynamic-overlay {
  background: linear-gradient(to right, var(--smartlearn-bg) 0%, color-mix(in srgb, var(--smartlearn-bg) 55%, transparent) 38%, transparent 72%);
  z-index: 1;
  pointer-events: none;
}
[dir="rtl"] .sl-hero-dynamic .sl-dynamic-overlay {
  background: linear-gradient(to left, var(--smartlearn-bg) 0%, color-mix(in srgb, var(--smartlearn-bg) 55%, transparent) 38%, transparent 72%);
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-dynamic .sl-btn-skew:hover {
    transform: skewX(-15deg) translateY(-2px);
  }
  [dir="rtl"] .sl-hero-dynamic .sl-btn-skew:hover {
    transform: skewX(15deg) translateY(-2px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-dynamic .sl-btn-skew {
    transition: none;
  }
}
@media (max-width: 991px) {
  .sl-hero-dynamic .sl-dynamic-image-wrapper {
    width: 100%;
    clip-path: none;
    opacity: 0.25;
  }
  [dir="rtl"] .sl-hero-dynamic .sl-dynamic-image-wrapper {
    clip-path: none;
  }
  .sl-hero-dynamic .sl-dynamic-overlay,
  [dir="rtl"] .sl-hero-dynamic .sl-dynamic-overlay {
    background: color-mix(in srgb, var(--smartlearn-bg) 78%, transparent);
  }
}
